export const CORRECTIONS = {"zoonoses--zoo-bacterial--taxonomic-hierarchy-example-colibacillosis-vs-q-fever":[{"severity":"contradicts","lectureSays":"ตารางในสไลด์เขียน Order ของ Colibacillosis ว่า Enterobacteriales","evidenceSays":"การวิเคราะห์ genome-based เสนอชื่อ order ที่ถูกต้องว่า Enterobacterales ord. nov. แบ่งเป็น 7 วงศ์ โดย Escherichia ยังคงอยู่ในวงศ์ Enterobacteriaceae ส่วนชื่อ Enterobacteriales ไม่เคยถูกตีพิมพ์อย่างถูกต้องตามหลักการตั้งชื่อ จึงถูกเขียนในเครื่องหมายคำพูดในเอกสารต้นฉบับ (PMID 27620848, DOI 10.1099/ijsem.0.001485) ส่วน Phylum, Class, Family, Genus, Species ที่เหลือในคอลัมน์นี้ไม่ได้ถูกโต้แย้ง","examAdvice":"ถ้าอาจารย์ธราดลออกตามตารางในสไลด์ให้ตอบ Enterobacteriales แต่จำชื่อที่ถูกต้องคือ Enterobacterales ไว้ด้วย","sourceRef":"PMID 27620848 (DOI 10.1099/ijsem.0.001485)"}],"zoonoses--zoo-corona--coronaviruses-overview-4-genus":[{"severity":"contradicts","lectureSays":"สไลด์เขียนว่า Delta-CoV คือ PED (Porcine Epidemic Diarrhea) ที่ทำให้หมูท้องเสีย","evidenceSays":"Porcine epidemic diarrhea virus (PEDV) จัดอยู่ใน genus Alphacoronavirus ส่วน coronavirus ของหมูที่อยู่ใน genus Deltacoronavirus คือ porcine deltacoronavirus (PDCoV) ซึ่งเป็นคนละเชื้อกัน แม้ทั้งคู่จะก่อ acute diarrhea อาเจียน และ dehydration ในลูกหมูแรกเกิดเหมือนกัน (review จาก Saif lab, Ohio State, PMID 27086031, DOI 10.1016/j.virusres.2016.04.009)","examAdvice":"ถ้าอาจารย์อลงกรณ์ออกตามสไลด์ให้ตอบ PED แต่จำให้แม่นว่าตัวจริงของ Delta คือ PDCoV และ PEDV เป็น Alpha","sourceRef":"PMID 27086031 (DOI 10.1016/j.virusres.2016.04.009)"}],"zoonoses--zoo-intro--zoonoses-emerging-diseases-historical-model":[{"severity":"contradicts","lectureSays":"สไลด์เขียนว่า 1918 H1N1 pandemic ทำให้คนตายเยอะมาก ประมาณ 1 ใน 5 ของประชากรโลก","evidenceSays":"การประมาณยอดผู้เสียชีวิตทั่วโลกจาก influenza pandemic ปี 1918-1920 อยู่ที่ราว 50 ล้านคน ปรับขึ้นจากการคำนวณยุค 1920s ที่ราว 21.5 ล้านคน และจากช่วง 24.7 ถึง 39.3 ล้านคนที่ปรับในปี 1991 โดยผู้เขียนระบุว่าตัวเลขจริงอาจถูกรายงานต่ำกว่าความเป็นจริงได้ถึงราว 100% เมื่อเทียบกับประชากรโลกราว 1.8 พันล้านคนจึงอยู่ที่ระดับ 3% ไม่ใช่ 1 ใน 5 (PMID 11875246, DOI 10.1353/bhm.2002.0022)","examAdvice":"ถ้าอาจารย์อลงกรณ์ออกตามสไลด์ให้ตอบ 1 ใน 5 แต่ต้องรู้ว่าเลขจริงคือตายราว 50 ล้านคน และ 1 ใน 5 คือสัดส่วนคนติดเชื้อ","sourceRef":"PMID 11875246 (DOI 10.1353/bhm.2002.0022)"}],"zoonoses--zoo-mycoses--yeast-appearance-culture-microscopic":[{"severity":"narrows","lectureSays":"สไลด์เขียนว่า colony ของ yeast บน agar เช่น blood agar มีลักษณะ กลม นูน เรียบ","evidenceSays":"ลักษณะ colony ของ yeast ขึ้นกับชนิดอาหารเลี้ยงเชื้อที่ใช้ เช่น yeast ที่แยกได้จากเลือดขึ้นเป็น colony สีชมพูจางบน CHROMagar Candida และเมื่อเลี้ยงบน cornmeal agar แล้วดูด้วยกล้องจุลทรรศน์เห็นเป็น oval budding yeast cells ปนกับ rudimentary pseudohyphae เป็นบางส่วน ไม่พบแหล่งที่ระบุคำบรรยาย กลม นูน เรียบ บน blood agar โดยตรง (PMID 31471347)","examAdvice":"ตอบ กลม นูน เรียบ ตามสไลด์ได้ แต่ถ้าโจทย์ระบุ media มาให้ ให้ตอบตาม media นั้น","sourceRef":"PMID 31471347"}],"zoonoses--zoo-rabies--diagnostic-methods-woah-cdc":[{"severity":"contradicts","lectureSays":"สไลด์ NIAH เขียนว่า ELISA เป็น commercial kit ราคาถูกกว่าและ specific สูงเท่า FAVN ในหัวข้อ antibody detection สำหรับ export","evidenceSays":"WOAH ระบุว่าการยืนยัน antibody ก่อนเคลื่อนย้ายสัตว์ระหว่างประเทศรับเฉพาะ virus neutralisation คือ FAVN และ RFFIT ส่วน ELISA ใช้กับการเคลื่อนย้ายสัตว์ระหว่างประเทศหรือการค้าไม่ได้ โดย Table 1 ให้คะแนน VN เป็น +++ แต่ ELISA เป็นเครื่องหมายลบสำหรับ individual animal freedom from infection prior to movement และ ELISA ใช้ได้เฉพาะงานสนับสนุนนโยบายกำจัดโรคกับการติดตาม immune status หลังวัคซีน (WOAH Terrestrial Manual Chapter 3.1.18) ส่วนเกณฑ์ 0.5 IU/ml ที่สไลด์เขียนไว้นั้นถูกต้อง สอดคล้องกับ Briggs et al., Biologicals 1998;26(4):347-55 (PMID 10403038, DOI 10.1006/biol.1998.0162)","examAdvice":"ถ้าอาจารย์ NIAH ออกข้อสอบเอง ให้ตอบตามสไลด์ แต่ต้องรู้ว่าจริง ๆ WOAH ให้ใช้ได้แค่ FAVN กับ RFFIT ก่อนส่งออก","sourceRef":"WOAH Terrestrial Manual Chapter 3.1.18 และ PMID 10403038 (DOI 10.1006/biol.1998.0162)"}],"zoonoses--zoo-rabies--rabies-virus-characteristics-pathogenesis":[{"severity":"contradicts","lectureSays":"สไลด์ NIAH เขียนว่า genome ของ rabies virus เป็น negative-sense ssRNA ขนาด 11 kb มี 5 ยีน (N, P, M, G, L)","evidenceSays":"งาน complete genome sequencing ของ rabies virus จาก Chinese ferret-badger วัด full-length genome ได้ 11,923 nucleotides คือประมาณ 11.9 kb ซึ่งปัดเป็น ~12 kb และรายงานว่าความยาวของ 5 coding region (N, P, M, G, L) ค่อนข้างคงที่เมื่อเทียบกับ reference rabies viruses (PMID 20193207)","examAdvice":"ถ้าข้อสอบมีตัวเลือก 11 kb ตามสไลด์ ให้ตอบตามที่อาจารย์สอน แต่จำไว้ว่าค่าจริงคือ ~12 kb","sourceRef":"PMID 20193207"},{"severity":"contradicts","lectureSays":"สไลด์เขียนซ้ำว่า genome 11 kb ประกอบด้วย 5 โปรตีน N, P, M, G, L","evidenceSays":"ค่าที่วัดได้จริงคือ 11,923 nt คือ ~11.9 ถึง 12 kb ส่วนองค์ประกอบ 5 ยีน N, P, M, G, L ที่สไลด์เขียนนั้นถูกต้องและความยาวของ coding region ค่อนข้างคงที่ระหว่าง strain (PMID 20193207)","examAdvice":"จำลำดับยีน N, P, M, G, L ตามสไลด์ได้เลย แก้เฉพาะตัวเลขขนาด genome เป็น ~12 kb","sourceRef":"PMID 20193207"}],"zoonoses--zoo-siv-civ--swine-influenza-virus-siv-history-lineages":[{"severity":"narrows","lectureSays":"ไทม์ไลน์ในสไลด์เขียนว่า 1930 คือปีที่พบ SIV ครั้งแรกในหมูที่สหรัฐอเมริกา","evidenceSays":"หลักฐานแรกที่แสดงว่า swine influenza เกิดจาก filtrable virus มาจากการทดลองของ Shope ที่ Rockefeller Institute ตีพิมพ์ปี 1931 ใน J Exp Med เล่ม 54 ซึ่งศึกษา outbreak ช่วงปี 1929-1930 และพบว่า filtrable virus เพียงอย่างเดียวทำให้หมูป่วยเพียงเล็กน้อย ต้องให้ร่วมกับ Haemophilus influenzae suis จึงเกิดโรคเหมือน swine influenza จริง (PMID 19869924, DOI 10.1084/jem.54.3.373)","examAdvice":"ตอบ 1930 ตามไทม์ไลน์ในสไลด์ได้ แต่ถ้าโจทย์ถามถึงปีที่ตีพิมพ์งานของ Shope ให้ตอบ 1931","sourceRef":"PMID 19869924 (DOI 10.1084/jem.54.3.373)"}]};
